   1→//! Slint Renderer for User Apps
   2→//!
   3→//! Renders UI apps (chat, survey, ecomm) using Slint interpreter.
   4→//! This crate provides the Slint-specific rendering layer, separate from
   5→//! the platform shell (sthalam_shell) and other renderers (renderer_raylib).
   6→//!
   7→//! ## Key Functions
   8→//!
   9→//! - `prepare_page()`: Extracts app files from Scribe and generates browser shell
  10→//! - `launch_slint_app()`: Creates a self-managing app window with its own timer
  11→//! - `create_slint_app()`: Lower-level function to create a running app instance
  12→//! - `validate_slint_files()`: Validates Slint files before importing
  13→
  14→mod slint_runtime;
  15→mod page_runtime;
  16→mod slint_model_bindings;
  17→
  18→pub use slint_runtime::{SlintRuntime, AssetPickRequest};
  19→pub use slint_model_bindings::LuaSlintModel;
  20→pub use page_runtime::{generate_page_shell, write_shell_slint, AppTab, parse_exported_types, ExportedTypes};
  21→
  22→use butler::{Butler, PageUpdate, ScribeMessage};
  23→use slint::ComponentHandle;
  24→use lua_runtime::{LuaCommand, LuaRuntime, LuaRuntimeConfig, ActorScribeHandle, ScribeHandle, UiMutation, UiQuery};
  25→use ractor::ActorRef;
  26→use std::cell::RefCell;
  27→use std::collections::HashMap;
  28→use std::path::{Path, PathBuf};
  29→use std::rc::Rc;
  30→use std::sync::Arc;
  31→use std::time::Duration;
  32→use tokio::sync::RwLock;
  33→
  34→/// App manifest (manifest.json)
  35→#[derive(Debug, Clone, serde::Deserialize)]
  36→pub struct Manifest {
  37→    pub name: String,
  38→    pub version: String,
  39→    /// Slint UI entry point (required for Slint apps, None for Raylib)
  40→    #[serde(default)]
  41→    pub entry_ui: Option<String>,
  42→    pub entry_logic: String,
  43→    /// Renderer type: "slint" (default) or "raylib"
  44→    #[serde(default = "default_renderer")]
  45→    pub renderer: String,
  46→    /// Array properties that need VecModel tracking for incremental updates
  47→    #[serde(default)]
  48→    pub models: Vec<String>,
  49→    /// Window width (for raylib apps)
  50→    #[serde(default)]
  51→    pub width: Option<u32>,
  52→    /// Window height (for raylib apps)
  53→    #[serde(default)]
  54→    pub height: Option<u32>,
  55→    /// Target FPS (for raylib apps)
  56→    #[serde(default)]
  57→    pub target_fps: Option<u32>,
  58→}
  59→
  60→fn default_renderer() -> String {
  61→    "slint".to_string()
  62→}
  63→
  64→/// App version combining semantic version and content hash
  65→#[derive(Debug, Clone, serde::Serialize)]
  66→pub struct AppVersion {
  67→    pub semantic: String,
  68→    pub content_hash: String,
  69→    pub display: String,
  70→}
  71→
  72→impl AppVersion {
  73→    pub fn new(semantic: &str, files: &HashMap<String, String>) -> Self {
  74→        use sha2::{Digest, Sha256};
  75→        use std::collections::BTreeMap;
  76→
  77→        let mut hasher = Sha256::new();
  78→        let sorted: BTreeMap<_, _> = files.iter().collect();
  79→        for (path, content) in sorted {
  80→            hasher.update(path.as_bytes());
  81→            hasher.update(content.as_bytes());
  82→        }
  83→        let hash = hasher.finalize();
  84→        let content_hash = hex::encode(&hash[..4]);
  85→
  86→        Self {
  87→            semantic: semantic.to_string(),
  88→            content_hash: content_hash.clone(),
  89→            display: format!("{}-{}", semantic, content_hash),
  90→        }
  91→    }
  92→}
