  94→/// Window geometry for in-place reload
  95→#[derive(Debug, Clone)]
  96→pub struct WindowGeometry {
  97→    pub x: i32,
  98→    pub y: i32,
  99→    pub width: u32,
 100→    pub height: u32,
 101→}
