 168→// Scribe Helpers
 169→
 170→/// Get app files from Scribe's in-memory layer
 171→///
 172→/// **Why**: Scribe has the latest synced content; storage may be stale
 173→pub async fn get_app_files_from_scribe(
 174→    scribe: &ActorRef<ScribeMessage>,
 175→    app_name: &str,
 176→) -> Result<HashMap<String, String>, Box<dyn std::error::Error>> {
 177→    let (tx, rx) = tokio::sync::oneshot::channel();
 178→    scribe.cast(ScribeMessage::GetAppFiles {
 179→        app_name: app_name.to_string(),
 180→        reply: tx,
 181→    })?;
 182→    let result = rx.await??;
 183→    Ok(result)
 184→}
 185→
 186→/// Get app manifest from Scribe
 187→///
 188→/// **Why**: Need to check renderer field before deciding which runtime to use
 189→pub async fn get_app_manifest(
 190→    scribe: &ActorRef<ScribeMessage>,
 191→    app_name: &str,
 192→) -> Result<Manifest, Box<dyn std::error::Error + Send + Sync>> {
 193→    let files = get_app_files_from_scribe(scribe, app_name).await
 194→        .map_err(|e| format!("Failed to get app files: {}", e))?;
 195→
 196→    let manifest_content = files.get("manifest.json")
 197→        .ok_or_else(|| format!("manifest.json not found for app {}", app_name))?;
 198→
 199→    let manifest: Manifest = serde_json::from_str(manifest_content)
 200→        .map_err(|e| format!("Failed to parse manifest.json: {}", e))?;
 201→
 202→    Ok(manifest)
 203→}
 204→
 205→// Page Preparation
 206→
 207→/// Extract app and generate browser shell with tabs
 208→///
 209→/// **Architecture:**
 210→/// - Apps are components (not Windows)
 211→/// - Browser generates shell with Window + TabBar + imports App
 212→///
 213→/// **Returns:** PreparedPage with paths to shell and lua files
 214→///
 215→/// **scribe**: Scribe reference to read files from in-memory layer (latest synced content)
 216→pub async fn prepare_page(
 217→    butler: &Butler,
 218→    page_id: &str,
 219→    app_name: Option<&str>,
 220→    scribe: &ActorRef<ScribeMessage>,
 221→) -> Result<PreparedPage, Box<dyn std::error::Error>> {
 222→    use std::fs;
 223→
 224→    // Get page info for title
 225→    let page = butler.pages().get(page_id)?
 226→        .ok_or_else(|| format!("Page {} not found", page_id))?;
 227→    let page_name = page.meta.name.clone();
 228→
 229→    // Get all apps in this page (for tabs)
 230→    let all_apps = butler.apps().list(page_id)?;
 231→    if all_apps.is_empty() {
 232→        return Err(format!("No apps found in page {}", page_id).into());
 233→    }
 234→
 235→    // Determine which app to load
 236→    let app_name = match app_name {
 237→        Some(name) => name.to_string(),
 238→        None => all_apps.first().unwrap().clone(),
 239→    };
 240→
 241→    // Get all files from Scribe's in-memory layer (has latest synced content)
 242→    let files = get_app_files_from_scribe(scribe, &app_name).await?;
 243→
 244→    tracing::debug!(
 245→        page_id = %page_id,
 246→        app_name = %app_name,
 247→        file_count = files.len(),
 248→        all_apps = ?all_apps,
 249→        "Preparing page with tabs"
 250→    );
 251→
 252→    // Create temporary directory
 253→    let temp_dir = tempfile::tempdir()?;
 254→    let temp_path = temp_dir.path().to_path_buf();
 255→
 256→    // Extract app files
 257→    for (file_path, content) in &files {
 258→        let full_path = temp_path.join(file_path);
 259→
 260→        if let Some(parent) = full_path.parent() {
 261→            fs::create_dir_all(parent)?;
 262→        }
 263→
 264→        fs::write(&full_path, content)?;
 265→    }
 266→
 267→    // Get data layers from page (not from app files - permit is at page level)
 268→    let data_layers = butler.apps().list_data_layers(page_id).unwrap_or_default();
 269→    tracing::debug!(
 270→        page_id = %page_id,
 271→        data_layers = ?data_layers,
 272→        "Retrieved data layers from page"
 273→    );
 274→
 275→    let lua_path = temp_path.join("app.lua");
 276→
 277→    // Read models and version from manifest.json
 278→    let manifest_path = temp_path.join("manifest.json");
 279→    let (models, semantic_version) = if manifest_path.exists() {
 280→        match fs::read_to_string(&manifest_path) {
 281→            Ok(content) => {
 282→                match serde_json::from_str::<Manifest>(&content) {
 283→                    Ok(manifest) => (manifest.models, manifest.version),
 284→                    Err(e) => {
 285→                        tracing::warn!(
 286→                            page_id = %page_id,
 287→                            app_name = %app_name,
 288→                            error = %e,
 289→                            "Failed to parse manifest.json, using defaults"
 290→                        );
 291→                        (vec![], "0.0.0".to_string())
 292→                    }
 293→                }
 294→            }
 295→            Err(e) => {
 296→                tracing::warn!(
 297→                    page_id = %page_id,
 298→                    app_name = %app_name,
 299→                    error = %e,
 300→                    "Failed to read manifest.json, using defaults"
 301→                );
 302→                (vec![], "0.0.0".to_string())
 303→            }
 304→        }
 305→    } else {
 306→        (vec![], "0.0.0".to_string())
 307→    };
 308→
 309→    // Compute app version (semantic + content hash)
 310→    let version = AppVersion::new(&semantic_version, &files);
 311→    tracing::info!(
 312→        app_name = %app_name,
 313→        version = %version.display,
 314→        "App version computed"
 315→    );
 316→
 317→    // Build tabs for all apps
 318→    let tabs: Vec<AppTab> = all_apps
 319→        .iter()
 320→        .map(|name| AppTab {
 321→            name: name.clone(),
 322→            display_name: name.clone(),
 323→        })
 324→        .collect();
 325→
 326→    // Generate shell that imports the app (with version footer)
 327→    let app_slint_path = temp_path.join("app.slint");
 328→    let shell_source = generate_page_shell(&app_slint_path, &tabs, &app_name, &page_name, Some(&version.display));
 329→
 330→    // Write shell to temp directory
 331→    let shell_path = write_shell_slint(&temp_path, &shell_source)?;
 332→
 333→    tracing::info!(
 334→        page_id = %page_id,
 335→        page_name = %page_name,
 336→        app_name = %app_name,
 337→        shell_path = %shell_path.display(),
 338→        tabs_count = tabs.len(),
 339→        models = ?models,
 340→        "Generated browser shell with tabs"
 341→    );
 342→
 343→    // Prevent auto-cleanup
 344→    let _ = temp_dir.keep();
 345→
 346→    Ok(PreparedPage {
 347→        shell_path,
 348→        lua_path,
 349→        app_name,
 350→        page_id: page_id.to_string(),
 351→        page_name,
 352→        all_apps: tabs,
 353→        data_layers,
 354→        models,
 355→        temp_dir: temp_path,
 356→        restore_geometry: None,
 357→        version,
 358→    })
 359→}
 360→
 361→// App Creation
 362→
 363→/// Create a running Slint app from prepared page data
 364→///
 365→/// **Context**: Called when an app needs to be loaded with Slint renderer
 366→pub fn create_slint_app(
 367→    prepared: PreparedPage,
 368→    scribe_ref: ActorRef<ScribeMessage>,
 369→    butler: Arc<Butler>,
 370→    app_status: Option<Arc<RwLock<AppStatus>>>,
 371→) -> Option<RunningSlintApp> {
 372→    tracing::info!(
 373→        page_id = %prepared.page_id,
 374→        page_name = %prepared.page_name,
 375→        app_name = %prepared.app_name,
 376→        "Creating Slint app runtime"
 377→    );
 378→
 379→    // Get user identity and role from Butler
 380→    let app_ctx = butler.app_context(&prepared.page_id);
 381→    let user_did = app_ctx.user_did;
 382→    let user_name = app_ctx.user_name;
 383→    let user_role = app_ctx.user_role;
 384→
 385→    let raw_lua_code = match std::fs::read_to_string(&prepared.lua_path) {
 386→        Ok(code) => code,
 387→        Err(e) => {
 388→            let error_msg = format!("Failed to read Lua code: {}", e);
 389→            tracing::error!(%error_msg);
 390→            update_status_failed(&app_status, error_msg);
 391→            return None;
 392→        }
 393→    };
 394→
 395→    // Set package.path so require("module") finds .lua files in the app's temp directory
 396→    let lua_code = format!(
 397→        "package.path = '{}/?.lua;' .. package.path\n{}",
 398→        prepared.temp_dir.display(),
 399→        raw_lua_code
 400→    );
 401→
 402→    let slint_path = prepared.shell_path.clone();
 403→
 404→    // Create channels
 405→    let (ui_tx, ui_rx) = tokio::sync::mpsc::channel::<UiMutation>(256);
 406→    let (query_tx, query_rx) = tokio::sync::mpsc::channel::<UiQuery>(32);
 407→    let (page_update_tx, page_update_rx) = tokio::sync::mpsc::channel::<PageUpdate>(256);
 408→    let (tab_switch_tx, tab_switch_rx) = std::sync::mpsc::channel::<String>();
 409→    let (asset_pick_tx, asset_pick_rx) = std::sync::mpsc::channel::<AssetPickRequest>();
 410→
 411→    let page_id = prepared.page_id.clone();
 412→    let app_name = prepared.app_name.clone();
 413→
 414→    // Spawn Lua runtime
 415→    let navigate_tx = tab_switch_tx.clone();
 416→
 417→    let config = LuaRuntimeConfig {
 418→        page_id: page_id.clone(),
 419→        app_name: app_name.clone(),
 420→        scribe: ActorScribeHandle::new(scribe_ref.clone()),
 421→        user_did: user_did.clone(),
 422→        user_name: user_name.clone(),
 423→        user_role: user_role.clone(),
 424→        lua_code,
 425→        ui_enabled: true,
 426→        ui_tx: Some(ui_tx),
 427→        query_tx: Some(query_tx),
 428→        navigate_tx: Some(navigate_tx),
 429→    };
 430→
 431→    let (lua_thread, lua_tx) = match LuaRuntime::spawn(config) {
 432→        Ok((thread, tx)) => (thread, tx),
 433→        Err(e) => {
 434→            let error_msg = format!("Failed to spawn Lua worker: {}", e);
 435→            tracing::error!(%error_msg);
 436→            update_status_failed(&app_status, error_msg);
 437→            return None;
 438→        }
 439→    };
 440→
 441→    // Create Slint runtime
 442→    let mut slint_runtime = match SlintRuntime::load(
 443→        slint_path,
 444→        app_name.clone(),
 445→        ui_rx,
 446→        query_rx,
 447→        lua_tx.clone(),
 448→    ) {
 449→        Ok(runtime) => runtime,
 450→        Err(e) => {
 451→            let error_msg = format!("Failed to create SlintRuntime: {}", e);
 452→            tracing::error!(%error_msg);
 453→            update_status_failed(&app_status, error_msg);
 454→            return None;
 455→        }
 456→    };
 457→
 458→    slint_runtime.set_tab_switch_channel(tab_switch_tx);
 459→    slint_runtime.set_asset_pick_channel(asset_pick_tx);
 460→
 461→    if let Err(e) = slint_runtime.slint_instance().show() {
 462→        let error_msg = format!("Failed to show app window: {:?}", e);
 463→        tracing::error!(%error_msg);
 464→        update_status_failed(&app_status, error_msg);
 465→        return None;
 466→    }
 467→
 468→    // Restore window geometry if this is an in-place reload
 469→    if let Some(ref geom) = prepared.restore_geometry {
 470→        let window = slint_runtime.slint_instance().window();
 471→        window.set_position(slint::WindowPosition::Physical(slint::PhysicalPosition::new(
 472→            geom.x, geom.y,
 473→        )));
 474→        window.set_size(slint::WindowSize::Physical(slint::PhysicalSize::new(
 475→            geom.width,
 476→            geom.height,
 477→        )));
 478→    }
 479→
 480→    if let Err(e) = slint_runtime.setup_callbacks() {
 481→        let error_msg = format!("Failed to setup shell callbacks: {}", e);
 482→        tracing::error!(%error_msg);
 483→        update_status_failed(&app_status, error_msg);
 484→        return None;
 485→    }
 486→
 487→    // Initialize VecModels
 488→    if let Err(e) = slint_runtime.init_models(&prepared.models) {
 489→        tracing::warn!("Failed to init models from manifest: {}", e);
 490→    }
 491→
 492→    // Setup AppAPI global callbacks
 493→    if let Err(e) = slint_runtime.setup_global_callbacks() {
 494→        let error_msg = format!("Failed to setup global callbacks: {}", e);
 495→        tracing::error!(%error_msg);
 496→        update_status_failed(&app_status, error_msg);
 497→        return None;
 498→    }
 499→
 500→    // Subscribe to page updates
 501→    if let Err(e) = scribe_ref.cast(ScribeMessage::SubscribeToPageUpdates { tx: page_update_tx }) {
 502→        tracing::warn!("Failed to subscribe to page updates: {}", e);
 503→    }
 504→
 505→    // Note: Initial data loading is handled by scribe:bind() in on_init()
 506→    // which calls fetch_layer_data() to get the real layer snapshot from Scribe.
 507→    // We no longer send empty LoroChanged events here as they would override
 508→    // the real data fetched by scribe:bind().
 509→
 510→    // Update status to loaded
 511→    if let Some(ref status) = app_status {
 512→        if let Ok(mut s) = status.try_write() {
 513→            s.page_id = Some(prepared.page_id.clone());
 514→            s.app_name = Some(prepared.app_name.clone());
 515→            s.status = "loaded".to_string();
 516→            s.error = None;
 517→            s.loaded_at = Some(chrono::Utc::now().to_rfc3339());
 518→            s.version = Some(prepared.version.display.clone());
 519→        }
 520→    }
 521→
 522→    Some(RunningSlintApp {
 523→        app_name: prepared.app_name,
 524→        page_id: prepared.page_id,
 525→        page_name: prepared.page_name,
 526→        all_apps: prepared.all_apps,
 527→        slint_runtime,
 528→        lua_thread,
 529→        lua_tx,
 530→        page_update_rx,
 531→        tab_switch_rx,
 532→        asset_pick_rx,
 533→        version: prepared.version,
 534→    })
 535→}
 536→
 537→// Self-Managing App Window
 538→
 539→/// Launch a Slint app in a self-managing window
 540→///
 541→/// Creates the app, shows the window, and starts its own timer that processes
 542→/// page updates, UI mutations, asset picks, tab switches, and app restarts.
 543→///
 544→/// **Returns**: LaunchedApp with timer (must keep alive) and lua_tx for debug eval.
 545→/// The window itself is owned by Slint's event loop.
 546→pub fn launch_slint_app(
 547→    prepared: PreparedPage,
 548→    scribe_ref: ActorRef<ScribeMessage>,
 549→    butler: Arc<Butler>,
 550→    tokio_handle: tokio::runtime::Handle,
 551→    app_status: Option<Arc<RwLock<AppStatus>>>,
 552→) -> Option<LaunchedApp> {
 553→    // Create the running app
 554→    let running = create_slint_app(prepared, scribe_ref, butler.clone(), app_status.clone())?;
 555→    let lua_tx_out = running.lua_tx.clone();
 556→
 557→    // Internal state wrapped for timer closure (Rc is fine - Slint main thread only)
 558→    let running: Rc<RefCell<Option<RunningSlintApp>>> = Rc::new(RefCell::new(Some(running)));
 559→    let ready_rx: Rc<RefCell<Option<std::sync::mpsc::Receiver<(PreparedPage, ActorRef<ScribeMessage>)>>>> =
 560→        Rc::new(RefCell::new(None));
 561→    let pending_geometry: Rc<RefCell<Option<WindowGeometry>>> = Rc::new(RefCell::new(None));
 562→
 563→    // Self-managing timer - processes all events for this window
 564→    let timer = slint::Timer::default();
 565→    timer.start(slint::TimerMode::Repeated, Duration::from_millis(100), move || {
 566→        // Check for ready apps (restart/tab-switch completion)
 567→        if let Some(ref rx) = *ready_rx.borrow() {
 568→            while let Ok((mut new_prepared, new_scribe)) = rx.try_recv() {
 569→                // Restore geometry from before restart
 570→                if let Some(geom) = pending_geometry.borrow_mut().take() {
 571→                    new_prepared.restore_geometry = Some(geom);
 572→                }
 573→                if let Some(new_app) = create_slint_app(new_prepared, new_scribe, butler.clone(), app_status.clone()) {
 574→                    *running.borrow_mut() = Some(new_app);
 575→                }
 576→            }
 577→        }
 578→
 579→        let mut running_ref = running.borrow_mut();
 580→        let Some(running_app) = running_ref.as_mut() else { return };
 581→
 582→        // Forward page updates to Lua
 583→        while let Ok(update) = running_app.page_update_rx.try_recv() {
 584→            match update {
 585→                PageUpdate::LayerChanged { layer, ops, delta, full_data, created, .. } => {
 586→                    // Check if this is an app layer update (triggers restart)
 587→                    // Use bare layer name (Scribe uses bare names, no page_id/ prefix)
 588→                    // Only restart if there are actual operations (changes) - empty ops means
 589→                    // sync protocol sent update but content is identical
 590→                    let expected_app_layer = format!("app:{}", running_app.app_name);
 591→                    let has_ops = ops.as_ref().map(|o| !o.is_empty()).unwrap_or(false);
 592→                    if layer == expected_app_layer && !created && has_ops {
 593→                        tracing::info!(layer = %layer, "App layer updated - restarting");
 594→
 595→                        // Capture geometry, shutdown, schedule re-preparation
 596→                        let geom = capture_window_geometry(running_app);
 597→                        *pending_geometry.borrow_mut() = Some(geom);
 598→
 599→                        let _ = running_app.slint_runtime.slint_instance().hide();
 600→                        let _ = running_app.lua_tx.try_send(LuaCommand::Shutdown);
 601→
 602→                        let (tx, rx) = std::sync::mpsc::channel();
 603→                        *ready_rx.borrow_mut() = Some(rx);
 604→
 605→                        let butler = butler.clone();
 606→                        let page_id = running_app.page_id.clone();
 607→                        let app_name = running_app.app_name.clone();
 608→
 609→                        *running_ref = None;
 610→
 611→                        tokio_handle.spawn(async move {
 612→                            let scribe_ref = match butler.open_page(&page_id).await {
 613→                                Ok(s) => s,
 614→                                Err(e) => {
 615→                                    tracing::error!(error = %e, "Failed to open page for restart");
 616→                                    return;
 617→                                }
 618→                            };
 619→                            let prepared = match prepare_page(&butler, &page_id, Some(&app_name), &scribe_ref).await {
 620→                                Ok(p) => p,
 621→                                Err(e) => {
 622→                                    tracing::error!(error = %e, "Failed to prepare page for restart");
 623→                                    return;
 624→                                }
 625→                            };
 626→                            let _ = tx.send((prepared, scribe_ref));
 627→                            slint::invoke_from_event_loop(|| {}).ok();
 628→                        });
 629→                        return;
 630→                    }
 631→
 632→                    if created {
 633→                        let _ = running_app.lua_tx.try_send(LuaCommand::LayerDiscovered {
 634→                            layer_name: layer,
 635→                        });
 636→                    } else {
 637→                        let _ = running_app.lua_tx.try_send(LuaCommand::LoroChanged {
 638→                            layer_name: layer,
 639→                            ops,
 640→                            delta,
 641→                            full_data,  // Already Option<JsonValue> from PageUpdate
 642→                        });
 643→                    }
 644→                }
 645→
 646→                PageUpdate::Ephemeral { user_did, payload, .. } => {
 647→                    let _ = running_app.lua_tx.try_send(LuaCommand::Ephemeral { user_did, payload });
 648→                }
 649→
 650→                PageUpdate::PeerSubscribed { did, .. } => {
 651→                    let _ = running_app.lua_tx.try_send(LuaCommand::PeerJoined { user_did: did });
 652→                }
 653→
 654→                PageUpdate::PeerUnsubscribed { did } => {
 655→                    let _ = running_app.lua_tx.try_send(LuaCommand::PeerLeft { user_did: did });
 656→                }
 657→
 658→                PageUpdate::QueryUpdated { .. } => {}
 659→
 660→                PageUpdate::StructuredEphemeral { from_did, func, args } => {
 661→                    let _ = running_app.lua_tx.try_send(LuaCommand::StructuredEphemeral { from_did, func, args });
 662→                }
 663→            }
 664→        }
 665→
 666→        // Handle tab switch requests
 667→        while let Ok(new_app_name) = running_app.tab_switch_rx.try_recv() {
 668→            if new_app_name != running_app.app_name {
 669→                tracing::info!(
 670→                    from = %running_app.app_name,
 671→                    to = %new_app_name,
 672→                    "Tab switch requested"
 673→                );
 674→
 675→                let geom = capture_window_geometry(running_app);
 676→                *pending_geometry.borrow_mut() = Some(geom);
 677→
 678→                let _ = running_app.slint_runtime.slint_instance().hide();
 679→                let _ = running_app.lua_tx.try_send(LuaCommand::Shutdown);
 680→
 681→                let (tx, rx) = std::sync::mpsc::channel();
 682→                *ready_rx.borrow_mut() = Some(rx);
 683→
 684→                let butler = butler.clone();
 685→                let page_id = running_app.page_id.clone();
 686→
 687→                *running_ref = None;
 688→
 689→                tokio_handle.spawn(async move {
 690→                    let scribe_ref = match butler.open_page(&page_id).await {
 691→                        Ok(s) => s,
 692→                        Err(e) => {
 693→                            tracing::error!(error = %e, "Failed to open page for tab switch");
 694→                            return;
 695→                        }
 696→                    };
 697→                    let prepared = match prepare_page(&butler, &page_id, Some(&new_app_name), &scribe_ref).await {
 698→                        Ok(p) => p,
 699→                        Err(e) => {
 700→                            tracing::error!(error = %e, "Failed to prepare page for tab switch");
 701→                            return;
 702→                        }
 703→                    };
 704→                    let _ = tx.send((prepared, scribe_ref));
 705→                    slint::invoke_from_event_loop(|| {}).ok();
 706→                });
 707→                return;
 708→            }
 709→        }
 710→
 711→        // Process asset pick requests
 712→        while let Ok(request) = running_app.asset_pick_rx.try_recv() {
 713→            handle_asset_pick(
 714→                &request,
 715→                &running_app.page_id,
 716→                &running_app.lua_tx,
 717→                &butler,
 718→                &tokio_handle,
 719→            );
 720→        }
 721→
 722→        // Process UI mutations (Lua -> Slint)
 723→        if let Err(e) = running_app.slint_runtime.process_ui_mutations() {
 724→            tracing::warn!(error = %e, "Failed to process UI mutations");
 725→        }
 726→
 727→        // Process UI queries (Slint -> Lua)
 728→        running_app.slint_runtime.process_ui_queries();
 729→    });
 730→
 731→    Some(LaunchedApp {
 732→        timer,
 733→        lua_tx: lua_tx_out,
 734→    })
 735→}
 736→
 737→// Asset Handling
 738→
 739→/// Handle asset pick request - opens native file dialog and uploads selected file
 740→pub fn handle_asset_pick(
 741→    request: &AssetPickRequest,
 742→    page_id: &str,
 743→    lua_tx: &tokio::sync::mpsc::Sender<LuaCommand>,
 744→    butler: &Arc<Butler>,
 745→    tokio_handle: &tokio::runtime::Handle,
 746→) {
 747→    let filter_extensions: &[&str] = match request.filter.as_str() {
 748→        "images" => &["png", "jpg", "jpeg", "gif", "webp", "bmp", "svg"],
 749→        _ => &["*"],
 750→    };
 751→
 752→    let filter_name = match request.filter.as_str() {
 753→        "images" => "Images",
 754→        _ => "All Files",
 755→    };
 756→
 757→    let file = rfd::FileDialog::new()
 758→        .set_title("Select Asset")
 759→        .add_filter(filter_name, filter_extensions)
 760→        .pick_file();
 761→
 762→    let path = match file {
 763→        Some(p) => p,
 764→        None => {
 765→            tracing::info!("Asset pick cancelled by user");
 766→            return;
 767→        }
 768→    };
 769→
 770→    tracing::info!(path = %path.display(), "Asset selected");
 771→
 772→    let bytes = match std::fs::read(&path) {
 773→        Ok(b) => b,
 774→        Err(e) => {
 775→            tracing::error!(path = %path.display(), error = %e, "Failed to read asset file");
 776→            return;
 777→        }
 778→    };
 779→
 780→    let filename = path
 781→        .file_name()
 782→        .map(|n| n.to_string_lossy().to_string())
 783→        .unwrap_or_else(|| "unknown".to_string());
 784→
 785→    let mime_type = mime_guess::from_path(&path)
 786→        .first_or_octet_stream()
 787→        .to_string();
 788→
 789→    let size = bytes.len() as u64;
 790→
 791→    let butler = butler.clone();
 792→    let page_id = page_id.to_string();
 793→    let lua_tx = lua_tx.clone();
 794→
 795→    tokio_handle.spawn(async move {
 796→        match butler
 797→            .assets()
 798→            .upload(&page_id, &bytes, &filename, &mime_type)
 799→            .await
 800→        {
 801→            Ok(hash) => {
 802→                tracing::info!(
 803→                    filename = %filename,
 804→                    mime_type = %mime_type,
 805→                    size = size,
 806→                    hash = %hash,
 807→                    "Asset uploaded"
 808→                );
 809→
 810→                let _ = lua_tx.try_send(LuaCommand::AssetUploaded {
 811→                    hash,
 812→                    filename,
 813→                    mime_type,
 814→                    size,
 815→                });
 816→            }
 817→            Err(e) => {
 818→                tracing::error!(error = %e, "Failed to upload asset");
 819→            }
 820→        }
 821→    });
 822→}
 823→
 824→// Test App Creation
 825→
 826→/// Create a Slint app for testing — no Butler, no Scribe actor
 827→///
 828→/// **Context**: Reads app files from disk, uses any ScribeHandle impl (mock or real)
 829→/// **app_dir**: Directory containing manifest.json, app.slint, app.lua
 830→pub fn create_test_slint_app(
 831→    app_dir: &Path,
 832→    page_id: &str,
 833→    user_did: &str,
 834→    user_name: &str,
 835→    user_role: &str,
 836→    scribe: Arc<dyn ScribeHandle>,
 837→) -> Option<RunningSlintApp> {
 838→    use std::fs;
 839→
 840→    // Read manifest
 841→    let manifest_path = app_dir.join("manifest.json");
 842→    let manifest_content = match fs::read_to_string(&manifest_path) {
 843→        Ok(c) => c,
 844→        Err(e) => {
 845→            tracing::error!(path = %manifest_path.display(), error = %e, "Failed to read manifest.json");
 846→            return None;
 847→        }
 848→    };
 849→    let manifest: Manifest = match serde_json::from_str(&manifest_content) {
 850→        Ok(m) => m,
 851→        Err(e) => {
 852→            tracing::error!(error = %e, "Failed to parse manifest.json");
 853→            return None;
 854→        }
 855→    };
 856→
 857→    let app_name = manifest.name.clone();
 858→
 859→    // Read Lua code
 860→    let lua_path = app_dir.join(&manifest.entry_logic);
 861→    let raw_lua_code = match fs::read_to_string(&lua_path) {
 862→        Ok(code) => code,
 863→        Err(e) => {
 864→            tracing::error!(path = %lua_path.display(), error = %e, "Failed to read Lua code");
 865→            return None;
 866→        }
 867→    };
 868→
 869→    // Copy app files to temp dir
 870→    let temp_dir = match tempfile::tempdir() {
 871→        Ok(d) => d,
 872→        Err(e) => {
 873→            tracing::error!(error = %e, "Failed to create temp dir");
 874→            return None;
 875→        }
 876→    };
 877→    let temp_path = temp_dir.path().to_path_buf();
 878→
 879→    for entry in walkdir::WalkDir::new(app_dir).into_iter().filter_map(|e| e.ok()) {
 880→        if entry.file_type().is_file() {
 881→            let rel = entry.path().strip_prefix(app_dir).unwrap_or(entry.path());
 882→            let dest = temp_path.join(rel);
 883→            if let Some(parent) = dest.parent() {
 884→                let _ = fs::create_dir_all(parent);
 885→            }
 886→            let _ = fs::copy(entry.path(), &dest);
 887→        }
 888→    }
 889→
 890→    // Generate shell .slint (single tab, no page switching)
 891→    let app_slint_path = temp_path.join(manifest.entry_ui.as_deref().unwrap_or("app.slint"));
 892→    let tab = AppTab { name: app_name.clone(), display_name: app_name.clone() };
 893→    let shell_source = generate_page_shell(&app_slint_path, &[tab.clone()], &app_name, &app_name, None);
 894→    let shell_path = match write_shell_slint(&temp_path, &shell_source) {
 895→        Ok(p) => p,
 896→        Err(e) => {
 897→            tracing::error!(error = %e, "Failed to write shell slint");
 898→            return None;
 899→        }
 900→    };
 901→
 902→    // Create channels
 903→    let (ui_tx, ui_rx) = tokio::sync::mpsc::channel::<UiMutation>(256);
 904→    let (query_tx, query_rx) = tokio::sync::mpsc::channel::<UiQuery>(32);
 905→    let (_page_update_tx, page_update_rx) = tokio::sync::mpsc::channel::<PageUpdate>(256);
 906→    let (tab_switch_tx, tab_switch_rx) = std::sync::mpsc::channel::<String>();
 907→    let (asset_pick_tx, asset_pick_rx) = std::sync::mpsc::channel::<AssetPickRequest>();
 908→
 909→    // Set package.path so require("module") finds .lua files in the app's temp directory
 910→    let lua_code = format!(
 911→        "package.path = '{}/?.lua;' .. package.path\n{}",
 912→        temp_path.display(),
 913→        raw_lua_code
 914→    );
 915→
 916→    // Spawn Lua runtime
 917→    let config = LuaRuntimeConfig {
 918→        page_id: page_id.to_string(),
 919→        app_name: app_name.clone(),
 920→        scribe,
 921→        user_did: user_did.to_string(),
 922→        user_name: user_name.to_string(),
 923→        user_role: user_role.to_string(),
 924→        lua_code,
 925→        ui_enabled: true,
 926→        ui_tx: Some(ui_tx),
 927→        query_tx: Some(query_tx),
 928→        navigate_tx: None,
 929→    };
 930→
 931→    let (lua_thread, lua_tx) = match LuaRuntime::spawn(config) {
 932→        Ok((thread, tx)) => (thread, tx),
 933→        Err(e) => {
 934→            tracing::error!(error = %e, "Failed to spawn Lua worker");
 935→            return None;
 936→        }
 937→    };
 938→
 939→    // Create Slint runtime
 940→    let mut slint_runtime = match SlintRuntime::load(
 941→        shell_path,
 942→        app_name.clone(),
 943→        ui_rx,
 944→        query_rx,
 945→        lua_tx.clone(),
 946→    ) {
 947→        Ok(runtime) => runtime,
 948→        Err(e) => {
 949→            tracing::error!(error = %e, "Failed to create SlintRuntime");
 950→            return None;
 951→        }
 952→    };
 953→
 954→    slint_runtime.set_tab_switch_channel(tab_switch_tx);
 955→    slint_runtime.set_asset_pick_channel(asset_pick_tx);
 956→
 957→    if let Err(e) = slint_runtime.slint_instance().show() {
 958→        tracing::error!(error = ?e, "Failed to show app window");
 959→        return None;
 960→    }
 961→
 962→    if let Err(e) = slint_runtime.setup_callbacks() {
 963→        tracing::error!(error = %e, "Failed to setup shell callbacks");
 964→        return None;
 965→    }
 966→
 967→    if let Err(e) = slint_runtime.init_models(&manifest.models) {
 968→        tracing::warn!(error = %e, "Failed to init models from manifest");
 969→    }
 970→
 971→    if let Err(e) = slint_runtime.setup_global_callbacks() {
 972→        tracing::error!(error = %e, "Failed to setup global callbacks");
 973→        return None;
 974→    }
 975→
 976→    // Keep temp dir alive
 977→    let _ = temp_dir.keep();
 978→
 979→    let files: HashMap<String, String> = HashMap::new();
 980→    let version = AppVersion::new(&manifest.version, &files);
 981→
 982→    Some(RunningSlintApp {
 983→        app_name,
 984→        page_id: page_id.to_string(),
 985→        page_name: page_id.to_string(),
 986→        all_apps: vec![tab],
 987→        slint_runtime,
 988→        lua_thread,
 989→        lua_tx,
 990→        page_update_rx,
 991→        tab_switch_rx,
 992→        asset_pick_rx,
 993→        version,
 994→    })
 995→}
 996→
 997→/// Launch a self-managing test Slint app window
 998→///
 999→/// **Context**: Wraps create_test_slint_app() with a 100ms timer to pump UI mutations.
1000→/// No page-update/restart logic since test apps don't hot-reload.
1001→///
1002→/// **Returns**: LaunchedApp with timer (must keep alive) and lua_tx for commands.
1003→pub fn launch_test_slint_app(
1004→    app_dir: &Path,
1005→    page_id: &str,
1006→    user_did: &str,
1007→    user_name: &str,
1008→    user_role: &str,
1009→    scribe: Arc<dyn ScribeHandle>,
1010→) -> Option<LaunchedApp> {
1011→    let running = create_test_slint_app(app_dir, page_id, user_did, user_name, user_role, scribe)?;
1012→    let lua_tx_out = running.lua_tx.clone();
1013→
1014→    let running = Rc::new(RefCell::new(Some(running)));
1015→
1016→    let timer = slint::Timer::default();
1017→    timer.start(slint::TimerMode::Repeated, Duration::from_millis(100), move || {
1018→        let mut running_ref = running.borrow_mut();
1019→        let Some(running_app) = running_ref.as_mut() else { return };
1020→
1021→        // Process UI mutations (Lua -> Slint)
1022→        if let Err(e) = running_app.slint_runtime.process_ui_mutations() {
1023→            tracing::warn!(error = %e, "Failed to process UI mutations");
1024→        }
1025→
1026→        // Process UI queries (Slint -> Lua)
1027→        running_app.slint_runtime.process_ui_queries();
1028→    });
1029→
1030→    Some(LaunchedApp {
1031→        timer,
1032→        lua_tx: lua_tx_out,
1033→    })
1034→}
1035→
1036→// Slint Validation
1037→
1038→/// Validate all Slint files in a directory using the Slint compiler
1039→///
1040→/// **Context**: Called before importing pages/creating spaces to catch syntax errors early
1041→pub async fn validate_slint_files(page_dir: &std::path::Path) -> Result<(), String> {
1042→    use slint_interpreter::Compiler;
1043→    use walkdir::WalkDir;
1044→
1045→    // Only validate app.slint entry points, not helper files like theme.slint
1046→    // which may only contain globals and can't be compiled standalone.
1047→    let slint_files: Vec<PathBuf> = WalkDir::new(page_dir)
1048→        .into_iter()
1049→        .filter_map(|e| e.ok())
1050→        .filter(|e| e.path().file_name().map_or(false, |name| name == "app.slint"))
1051→        .map(|e| e.path().to_path_buf())
1052→        .collect();
1053→
1054→    if slint_files.is_empty() {
1055→        return Ok(());
1056→    }
1057→
1058→    tokio::task::spawn_blocking(move || {
1059→        let rt = tokio::runtime::Builder::new_current_thread()
1060→            .enable_all()
1061→            .build()
1062→            .map_err(|e| format!("Failed to create runtime: {}", e))?;
1063→
1064→        let mut errors = Vec::new();
1065→
1066→        for slint_path in slint_files {
1067→            tracing::info!("Validating Slint file: {}", slint_path.display());
1068→            let compiler = Compiler::default();
1069→            let result = rt.block_on(compiler.build_from_path(&slint_path));
1070→
1071→            let compile_errors: Vec<_> = result
1072→                .diagnostics()
1073→                .filter(|d| d.level() == slint_interpreter::DiagnosticLevel::Error)
1074→                .map(|d| d.to_string())
1075→                .collect();
1076→
1077→            if !compile_errors.is_empty() {
1078→                errors.push(format!("{}:\n  {}", slint_path.display(), compile_errors.join("\n  ")));
1079→            }
1080→        }
1081→
1082→        if errors.is_empty() {
1083→            Ok(())
1084→        } else {
1085→            Err(format!("Slint compilation errors:\n{}", errors.join("\n")))
1086→        }
1087→    })
1088→    .await
1089→    .map_err(|e| format!("Validation task failed: {}", e))?
1090→}
1091→
1092→// Internal Helpers
1093→
1094→/// Capture window geometry for in-place reload
1095→fn capture_window_geometry(app: &RunningSlintApp) -> WindowGeometry {
1096→    let window = app.slint_runtime.slint_instance().window();
1097→    let win_pos = window.position();
1098→    let win_size = window.size();
1099→    WindowGeometry {
1100→        x: win_pos.x,
1101→        y: win_pos.y,
1102→        width: win_size.width,
1103→        height: win_size.height,
1104→    }
1105→}
1106→
1107→/// Update app status to failed
1108→fn update_status_failed(app_status: &Option<Arc<RwLock<AppStatus>>>, error_msg: String) {
1109→    if let Some(ref status) = app_status {
1110→        if let Ok(mut s) = status.try_write() {
1111→            s.status = "failed".to_string();
1112→            s.error = Some(error_msg);
1113→        }
1114→    }
1115→}
1116→

