355→            let app_name = app_name.to_string();
356→            let app_dir = PathBuf::from(app_dir.to_string());
357→            tracing::info!(app_name = %app_name, app_dir = %app_dir.display(), "Refresh app");
358→
359→            let butler = butler.clone();
360→
361→            tokio_handle.spawn(async move {
362→                // Find page containing this app by searching Butler's spaces/pages
363→                let page_id = find_page_for_app(&butler, &app_name);
364→
365→                if let Some(page_id) = page_id {
366→                    match butler.open_page(&page_id).await {
367→                        Ok(scribe_ref) => {
368→                            let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
369→                            if let Err(e) = scribe_ref.cast(ScribeMessage::RefreshApp {
370→                                app_name: app_name.clone(),
371→                                app_dir,
372→                                reply: reply_tx,
373→                            }) {
374→                                tracing::error!(error = %e, "Failed to send RefreshApp to Scribe");
375→                                return;
376→                            }
377→
378→                            match reply_rx.await {
379→                                Ok(Ok(changed_files)) => {
380→                                    tracing::info!(
381→                                        app_name = %app_name,
382→                                        changed_count = changed_files.len(),
383→                                        "App refreshed"
384→                                    );
385→                                }
386→                                Ok(Err(e)) => {
387→                                    tracing::error!(error = %e, "RefreshApp failed");
388→                                }
389→                                Err(_) => {
390→                                    tracing::error!("RefreshApp reply channel closed");
391→                                }
392→                            }
393→                        }
394→                        Err(e) => {
395→                            tracing::error!(error = %e, page_id = %page_id, "Failed to open page for refresh");
396→                        }
397→                    }
398→                } else {
399→                    tracing::warn!(app_name = %app_name, "Could not find page containing app");
400→                }
401→            });
402→        });
403→    }
404→
405→    // Collector timer: poll app_ready channel, launch windows, connect debug eval
406→
407→    let collector_timer = {
408→        let app_timers = app_timers.clone();
409→        let butler = butler.clone();
410→        let tokio_handle = tokio_handle.clone();
411→        let app_status = app_status.clone();
412→        let debug_server = debug_server.clone();
413→
414→        let timer = slint::Timer::default();
415→        timer.start(
416→            slint::TimerMode::Repeated,
417→            std::time::Duration::from_millis(100),
418→            move || {
419→                while let Ok((prepared, scribe_ref)) = app_ready_rx.try_recv() {
420→                    tracing::info!(
421→                        page_id = %prepared.page_id,
422→                        app_name = %prepared.app_name,
423→                        "Launching app window"
424→                    );
425→
426→                    if let Some(launched) = renderer_slint::launch_slint_app(
427→                        prepared,
428→                        scribe_ref,
429→                        butler.clone(),
430→                        tokio_handle.clone(),
431→                        app_status.clone(),
432→                    ) {
433→                        // Connect debug eval bridge if debug server is active
434→                        if let Some(ref server) = debug_server {
435→                            let lua_tx = launched.lua_tx.clone();
436→
437→                            // Create eval channel: ControlServer -> forwarding task -> LuaCommand
438→                            let (eval_tx, mut eval_rx) =
439→                                tokio::sync::mpsc::channel::<DebugEvalRequest>(32);
440→                            server.set_eval_channel(eval_tx);
441→
442→                            let lua_tx_for_eval = lua_tx.clone();
443→                            tokio_handle.spawn(async move {
444→                                while let Some(req) = eval_rx.recv().await {
445→                                    let (reply_tx, reply_rx) = tokio::sync::oneshot::channel();
446→                                    if lua_tx_for_eval
447→                                        .send(lua_runtime::LuaCommand::DebugEval {
448→                                            code: req.code,
449→                                            response_tx: reply_tx,
450→                                        })
451→                                        .await
452→                                        .is_ok()
453→                                    {
454→                                        let result = reply_rx.await.unwrap_or_else(|_| {
455→                                            Err("Eval reply channel closed".to_string())
456→                                        });
457→                                        let _ = req.response_tx.send(result);
458→                                    } else {
459→                                        let _ = req
460→                                            .response_tx
461→                                            .send(Err("Lua worker channel closed".to_string()));
462→                                    }
463→                                }
464→                            });
465→
466→                            // Also set direct lua_worker_tx for the control server
467→                            server.set_lua_worker_channel(lua_tx);
468→                        }
469→
470→                        app_timers.borrow_mut().push(launched);
471→                    }
472→                }
473→            },
474→        );
475→        timer
476→    };
477→
478→    // UI automation timer (if debug server is enabled)
479→
480→    let _ui_timer = if let Some(mut ui_rx) = ui_rx {
481→        let shell_weak = shell.as_weak();
482→        let timer = slint::Timer::default();
483→        timer.start(
484→            slint::TimerMode::Repeated,
485→            std::time::Duration::from_millis(16), // ~60fps
486→            move || {
487→                if let Some(shell) = shell_weak.upgrade() {
488→                    ui_automation::process_ui_commands(&shell, &mut ui_rx);
489→                }
490→            },
491→        );
492→        Some(timer)
493→    } else {
494→        None
495→    };
496→
497→    // Keep timers alive
498→    let _collector_timer = collector_timer;
499→    let _app_timers = app_timers;
500→
501→    // Run the shell
502→    shell.run().expect("Failed to run shell");
503→}
504→
505→/// Spawn background task to auto-reconnect to stored nodes
506→fn spawn_auto_reconnect(butler: Arc<Butler>, handle: CourierHandle) {
507→    tokio::spawn(async move {
508→        // Owner-side: Reconnect to sovereign nodes
509→        let nodes = butler.nodes().list().unwrap_or_default();
510→        for node in nodes {
511→            tracing::info!(name = %node.name, node_id = %node.node_id, "Auto-connecting to sovereign node");
512→            if let Some(permit) = &node.permit {
513→                if let Err(e) = handle.connect(&node.node_id, permit) {
514→                    tracing::warn!(name = %node.name, error = %e, "Failed to initiate connection");
515→                    let _ = butler.nodes().set_connected(&node.node_id, false);
516→                }
517→            } else {
518→                tracing::info!(name = %node.name, "No permit stored, skipping");
519→                let _ = butler.nodes().set_connected(&node.node_id, false);
520→            }
521→        }
522→
523→        // Viewer-side: Reconnect to node contacts
524→        let node_contacts = butler.contacts().list_nodes().unwrap_or_default();
525→        for contact in node_contacts {
526→            if let (Some(node_id), Some(permit)) = (&contact.node_id, &contact.permit) {
527→                tracing::info!(name = %contact.username, node_id = %node_id, "Auto-connecting to node contact");
528→                if let Err(e) = handle.connect(node_id, permit) {
529→                    tracing::warn!(name = %contact.username, error = %e, "Failed to initiate viewer connection");
530→                }
531→            }
532→        }
533→    });
534→}
535→
536→/// Find the page that contains a given app by searching all spaces/pages
537→fn find_page_for_app(butler: &Butler, app_name: &str) -> Option<String> {
538→    let spaces = butler.spaces().list().ok()?;
539→    for space in &spaces {
540→        let pages = butler.pages().list(&space.id).ok()?;
541→        for page in &pages {
542→            let apps = butler.apps().list(&page.id).ok()?;
543→            if apps.iter().any(|a| a == app_name) {
544→                return Some(page.id.clone());
545→            }
546→        }
547→    }
548→    None
549→}
550→
551→/// Launch a Raylib app (when manifest.renderer == "raylib")
552→#[cfg(feature = "raylib")]
553→async fn launch_raylib_app(
554→    page_id: &str,
555→    app_name: &str,
556→    butler: Arc<Butler>,
557→    scribe_ref: ractor::ActorRef<ScribeMessage>,
558→    manifest: renderer_slint::Manifest,
559→) {
560→    let files = match renderer_slint::get_app_files_from_scribe(&scribe_ref, app_name).await {
561→        Ok(f) => f,
562→        Err(e) => {
563→            tracing::error!(error = %e, "Failed to get app files for Raylib app");
564→            return;
565→        }
566→    };
567→
568→    let lua_code = match files.get("app.lua").or_else(|| files.get(&manifest.entry_logic)) {
569→        Some(code) => code.clone(),
570→        None => {
571→            tracing::error!("No Lua entry file found for Raylib app");
572→            return;
573→        }
574→    };
575→
576→    let game_manifest = renderer_raylib::GameManifest {
577→        name: manifest.name.clone(),
578→        version: manifest.version.clone(),
579→        entry_logic: manifest.entry_logic.clone(),
580→        width: manifest.width.unwrap_or(800),
581→        height: manifest.height.unwrap_or(600),
582→        target_fps: manifest.target_fps.unwrap_or(60),
583→    };
584→
585→    if let Err(e) = renderer_raylib::spawn_app(
586→        page_id,
587→        app_name,
588→        butler,
589→        scribe_ref,
590→        game_manifest,
591→        lua_code,
592→    ) {
593→        tracing::error!(error = %e, "Failed to spawn Raylib app");
594→    }
595→}
596→
597→/// Setup profiling tools (tokio-console and/or tracing-flame)
598→///
599→/// **Modes** (based on environment variables):
600→/// - `FLAME_OUTPUT` + `TOKIO_CONSOLE_PORT` → both layers
601→/// - `FLAME_OUTPUT` only → flame layer only (no console overhead)
602→/// - `TOKIO_CONSOLE_PORT` only → console layer only
603→///
604→/// **Environment variables**:
605→/// - `TOKIO_CONSOLE_PORT`: Port for tokio-console (enables console layer)
606→/// - `FLAME_OUTPUT`: Path for flame graph output file (enables flame layer)
607→#[cfg(feature = "profiling")]
608→fn setup_profiling() -> Option<tracing_flame::FlushGuard<std::io::BufWriter<File>>> {
609→    use tracing_subscriber::prelude::*;
610→
611→    let console_port: Option<u16> = std::env::var("TOKIO_CONSOLE_PORT")
612→        .ok()
613→        .and_then(|p| p.parse().ok());
614→    let flame_path = std::env::var("FLAME_OUTPUT").ok();
615→
616→    match (&flame_path, console_port) {
617→        // Both flame + console
618→        (Some(path), Some(port)) => {
619→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
620→                Ok((layer, guard)) => (Some(layer), Some(guard)),
621→                Err(e) => {
622→                    eprintln!("Failed to create flame layer: {}", e);
623→                    (None, None)
624→                }
625→            };
626→
627→            let console_layer = console_subscriber::ConsoleLayer::builder()
628→                .server_addr(([127, 0, 0, 1], port))
629→                .spawn();
630→
631→            tracing_subscriber::registry()
632→                .with(console_layer)
633→                .with(flame_layer)
634→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
635→                .init();
636→
637→            tracing::info!(port = port, path = %path, "Profiling: tokio-console + flame");
638→            guard
639→        }
640→        // Flame only (no console overhead)
641→        // Filter out tokio runtime TRACE spans (normally consumed by console-subscriber)
642→        (Some(path), None) => {
643→            let (flame_layer, guard) = match tracing_flame::FlameLayer::with_file(path) {
644→                Ok((layer, guard)) => (Some(layer), Some(guard)),
645→                Err(e) => {
646→                    eprintln!("Failed to create flame layer: {}", e);
647→                    (None, None)
648→                }
649→            };
650→
651→            let filter = tracing_subscriber::EnvFilter::new(
652→                "info,tokio=off,runtime=off",
653→            );
654→
655→            tracing_subscriber::registry()
656→                .with(filter)
657→                .with(flame_layer)
658→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
659→                .init();
660→
661→            tracing::info!(path = %path, "Profiling: flame only (no console overhead)");
662→            guard
663→        }
664→        // Console only
665→        (None, Some(port)) => {
666→            let console_layer = console_subscriber::ConsoleLayer::builder()
667→                .server_addr(([127, 0, 0, 1], port))
668→                .spawn();
669→
670→            tracing_subscriber::registry()
671→                .with(console_layer)
672→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
673→                .init();
674→
675→            tracing::info!(port = port, "Profiling: tokio-console only");
676→            None
677→        }
678→        // Neither - just fmt logging
679→        (None, None) => {
680→            let filter = tracing_subscriber::EnvFilter::new(
681→                "info,tokio=off,runtime=off",
682→            );
683→
684→            tracing_subscriber::registry()
685→                .with(filter)
686→                .with(tracing_subscriber::fmt::layer().with_target(true).with_level(true))
687→                .init();
688→
689→            tracing::info!("Profiling feature enabled but no FLAME_OUTPUT or TOKIO_CONSOLE_PORT set");
690→            None
691→        }
692→    }
693→}
